def test_inputs_not_mutated():
    base = {"A": 1, "B": 2}
    incoming = {"A": 3, "C": 4}
    base_copy = copy.deepcopy(base)
    incoming_copy = copy.deepcopy(incoming)
    result = merge_inventory(base, incoming)
